# =====================================================================
# NaijaDrops Fix Script #2 - generated by Claude
# Fixes in this batch:
#   1. REAL negotiation, both pre-match and post-match:
#      - Pre-match: a rider can now actually submit a price bid on a job
#        before being matched (IncomingOrderCard had the wiring but no UI
#        at all for it - fixed). The vendor sees incoming bids on the
#        tracking page while waiting for a rider and can Accept or
#        Decline each one; accepting is what creates the match.
#      - Post-match: the in-chat "negotiate price" panel no longer writes
#        agreed_price the instant either side hits Confirm. It now posts a
#        pending offer that the OTHER party must explicitly Accept or
#        Decline in chat before the price actually changes.
#      - Also fixed a real security gap found while doing this: accept_bid
#        never checked the caller was actually the order's vendor.
#   2. Map-link resolution: pasting a Google Maps / WhatsApp share link
#      (including short links like maps.app.goo.gl) into the location
#      search boxes in the main vendor delivery flow now actually resolves
#      it, instead of being sent to the geocoder as plain text and quietly
#      returning nothing.
#   3. App-wide error boundary (error.jsx + global-error.jsx) so an
#      unexpected crash anywhere shows a friendly retry screen instead of
#      Next.js's default error page.
#
# Run this from the ROOT of your NaijaDrops project folder
# (the folder that contains "src", "package.json", etc.)
#
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\Fix-NaijaDrops-Negotiation-Links.ps1
# =====================================================================

$ErrorActionPreference = "Stop"
$ts = Get-Date -Format "yyyyMMdd_HHmmss"
$root = Get-Location

function Write-FileNoBom {
    param([string]$RelativePath, [string]$Base64Content)

    $fullPath = Join-Path $root $RelativePath
    $dir = Split-Path $fullPath -Parent

    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        Write-Host "  Created directory: $dir" -ForegroundColor DarkGray
    }

    if (Test-Path -LiteralPath $fullPath) {
        $backupPath = "$fullPath.bak_$ts"
        Copy-Item -LiteralPath $fullPath -Destination $backupPath -Force
        Write-Host "  Backed up existing file to: $(Split-Path $backupPath -Leaf)" -ForegroundColor DarkGray
    }

    $bytes = [System.Convert]::FromBase64String($Base64Content)
    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    $noBomUtf8 = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($fullPath, $text, $noBomUtf8)

    Write-Host "  Wrote: $RelativePath" -ForegroundColor Green
}

Write-Host ""
Write-Host "NaijaDrops fix script #2 starting..." -ForegroundColor Cyan
Write-Host "Project root: $root" -ForegroundColor Cyan
Write-Host ""

Write-Host "Processing: src/components/OrderChat.jsx" -ForegroundColor White
